from __future__ import annotations
import math
NORMALIZATION = 2.0 * math.pi * math.e

def entropy_power(n: int, h: float) -> float:
    if n <= 0: raise ValueError("n must be positive")
    return math.exp(2.0 * h / n) / NORMALIZATION

def entropy_radius(n: int, h: float) -> float:
    if n <= 0: raise ValueError("n must be positive")
    return math.exp(h / n) / math.sqrt(NORMALIZATION)

def boundary(n: int, hx: float, hy: float) -> float:
    if n <= 0: raise ValueError("n must be positive")
    m = max(hx, hy)
    return m + n / 2.0 * math.log(math.exp(2*(hx-m)/n) + math.exp(2*(hy-m)/n))

for n, h in [(1,-0.7),(2,1.2),(10,8.0),(100,125.0)]:
    p, r = entropy_power(n,h), entropy_radius(n,h)
    print(n, h, p, r*r, p-r*r)
    assert math.isclose(p, r*r, rel_tol=1e-12, abs_tol=1e-12)

