    m = max(hx, hy)
    return m + n / 2.0 * math.log(math.exp(2*(hx-m)/n) + math.exp(2*(hy-m)/n))

def deficit(n: int, hx: float, hy: float, hs: float) -> float:
    return entropy_power(n,hs)-entropy_power(n,hx)-entropy_power(n,hy)

n, hx, hy = 8, 0.4, 1.7
b = boundary(n,hx,hy)
base = entropy_power(n,hx)+entropy_power(n,hy)
for delta in [0.0,0.05,0.5,2.0]:
    observed = deficit(n,hx,hy,b+delta)
    predicted = math.expm1(2*delta/n)*base
    print(delta, observed, predicted, observed-predicted)
    assert math.isclose(observed,predicted,rel_tol=1e-12,abs_tol=1e-12)

