from __future__ import annotations
import math

def sharp_boundary(n: int, h_x: float, h_y: float) -> float:
    if n <= 0: raise ValueError("n must be positive")
    m = max(h_x, h_y)
    return m + 0.5*n*math.log(math.exp(2*(h_x-m)/n)+math.exp(2*(h_y-m)/n))

print(sharp_boundary(50, 10000.0, 9990.0))

