def entropy_radius(n: int, h: float) -> float:
    if n <= 0: raise ValueError("n must be positive")
    return math.exp(h / n) / math.sqrt(NORMALIZATION)

def boundary(n: int, hx: float, hy: float) -> float:
    if n <= 0: raise ValueError("n must be positive")
    m = max(hx, hy)
    return m + n / 2.0 * math.log(math.exp(2*(hx-m)/n) + math.exp(2*(hy-m)/n))

def diagnose(n: int, hx: float, hy: float, hs: float) -> dict[str,float]:
    px, py, ps = (entropy_power(n,h) for h in (hx,hy,hs))
    rx, ry, rs = (entropy_radius(n,h) for h in (hx,hy,hs))
    return {"deficit": ps-px-py, "radius_gap": rs*rs-rx*rx-ry*ry,
            "x_residual": px-rx*rx, "y_residual": py-ry*ry,
            "sum_residual": ps-rs*rs}

print(diagnose(4, 0.2, 1.1, boundary(4,0.2,1.1)+0.3))

from __future__ import annotations
import math

def entropy_excess_from_deficit(n: int, base_power: float, deficit: float) -> float:
    if n <= 0 or base_power <= 0 or deficit <= -base_power:
        raise ValueError("invalid domain")
    return 0.5*n*math.log1p(deficit/base_power)

print(entropy_excess_from_deficit(8, 3.0, 0.5))

